import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import AdminDepartments from './admin/AdminDepartments';
import AdminUsers from './admin/AdminUsers';
import AdminPapers from './admin/AdminPapers';

const TABS = [
  { key:'departments', label:'🏢 Departments' },
  { key:'users',       label:'👥 Users' },
  { key:'papers',      label:'📄 Papers' },
];

export default function AdminDashboard() {
  const { user } = useAuth();
  const [tab, setTab] = useState('departments');

  return (
    <div>
      <Navbar title="QR Office Admin" greeting={`Welcome, ${user?.username}! You are Administrator`} />
      <div className="tabs">
        {TABS.map(t => (
          <button key={t.key} className={`tab ${tab===t.key?'active':''}`} onClick={() => setTab(t.key)}>
            {t.label}
          </button>
        ))}
      </div>
      <div className="page">
        <div style={{ background: 'linear-gradient(135deg, #0052CC, #1E73FF)', borderRadius: '12px', padding: '24px', marginBottom: '24px', color: '#fff' }}>
          <h2 style={{ fontSize: '24px', fontWeight: '700', marginBottom: '8px' }}>Welcome, {user?.username}! 👋</h2>
          <p style={{ fontSize: '14px', opacity: '0.9' }}>You are logged in as <strong>Administrator</strong></p>
        </div>
        {tab === 'departments' && <AdminDepartments />}
        {tab === 'users'       && <AdminUsers />}
        {tab === 'papers'      && <AdminPapers />}
      </div>
    </div>
  );
}
